    def _dataset(
        self, job: IngestionJob, dataset_id: str, records: tuple[NormalizedRecord, ...]
    ) -> TimeFDataset:
        try:
            license_value = next(
                item for item in License if item.value.casefold() == job.dataset_license_id.casefold()
            )
        except StopIteration:
