"""Human-approved implementation decisions layered over immutable semantic specs."""

from __future__ import annotations

from dataclasses import asdict, dataclass
import hashlib
import json
from pathlib import Path
import re
from typing import Any

from .models import DatasetSpec, EvidenceClaim, EvidenceStatus


HUMAN_CONFIRMATION = "human_confirmation"
_FIELD_TOKEN = re.compile(r"([A-Za-z_][A-Za-z0-9_]*)(?:\[([0-9]+)\])?")


class ImplementationHandoffError(ValueError):
    """Report an invalid downstream requirement or implementation override."""


@dataclass(frozen=True)
class DownstreamRequirement:
    """Describe one semantic value required by a downstream interface."""

    field_path: str
    downstream_system: str
    requirement: str
    best_supported_candidate: Any = None
    supporting_evidence_refs: tuple[str, ...] = ()
    remaining_uncertainty: str | None = None

    @classmethod
    def from_dict(cls, raw: dict[str, Any]) -> DownstreamRequirement:
        return cls(
            field_path=raw["field_path"],
            downstream_system=raw["downstream_system"],
            requirement=raw["requirement"],
            best_supported_candidate=raw.get("best_supported_candidate"),
            supporting_evidence_refs=tuple(raw.get("supporting_evidence_refs", ())),
            remaining_uncertainty=raw.get("remaining_uncertainty"),
        )


@dataclass(frozen=True)
class BlockingUnresolvedField:
    """Expose an unresolved semantic field that prevents implementation."""

    field_path: str
    semantic_resolution: str
    semantic_value: Any
    downstream_system: str
    requirement: str
    best_supported_candidate: Any
    supporting_evidence_refs: tuple[str, ...]
    remaining_uncertainty: str | None


@dataclass(frozen=True)
class ImplementationOverride:
    """Record an approved downstream value that is not semantic evidence."""

    override_id: str
    field_path: str
    value: Any
    source: str
    approved_by: str
    rationale: str
    downstream_system: str
    evidence_refs: tuple[str, ...] = ()

    @classmethod
    def from_dict(cls, raw: dict[str, Any]) -> ImplementationOverride:
        return cls(
            override_id=raw["override_id"],
            field_path=raw["field_path"],
            value=raw.get("value"),
            source=raw.get("source", ""),
            approved_by=raw.get("approved_by", ""),
            rationale=raw.get("rationale", ""),
            downstream_system=raw.get("downstream_system", ""),
            evidence_refs=tuple(raw.get("evidence_refs", ())),
        )


@dataclass(frozen=True)
class ImplementationOverrideArtifact:
    """Bind decisions and requirements to one semantic-spec snapshot."""

    schema_version: str
    dataset_id: str
    semantic_spec_sha256: str
    requirements: tuple[DownstreamRequirement, ...]
    overrides: tuple[ImplementationOverride, ...]
    downstream_context: dict[str, Any] | None = None

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    def to_json(self, *, indent: int = 2) -> str:
        return json.dumps(self.to_dict(), indent=indent, allow_nan=False) + "\n"

    @classmethod
    def from_dict(cls, raw: dict[str, Any]) -> ImplementationOverrideArtifact:
        if raw.get("schema_version") != "1.0":
            raise ImplementationHandoffError(
                "unsupported implementation-override schema_version; expected '1.0'"
            )
        return cls(
            schema_version="1.0",
            dataset_id=raw["dataset_id"],
            semantic_spec_sha256=raw["semantic_spec_sha256"],
            requirements=tuple(
                DownstreamRequirement.from_dict(item)
                for item in raw.get("requirements", ())
            ),
            overrides=tuple(
                ImplementationOverride.from_dict(item)
                for item in raw.get("overrides", ())
            ),
            downstream_context=raw.get("downstream_context"),
        )

    @classmethod
    def read_json(cls, path: str | Path) -> ImplementationOverrideArtifact:
        raw = json.loads(Path(path).read_text(encoding="utf-8"))
        if not isinstance(raw, dict):
            raise ImplementationHandoffError(
                "implementation-override JSON root must be an object"
            )
        return cls.from_dict(raw)


@dataclass(frozen=True)
class ConnectorHandoff:
    """Connector view with semantic truth and decisions kept separate."""

    schema_version: str
    dataset_id: str
    semantic_spec_sha256: str
    semantic_spec: dict[str, Any]
    blocking_unresolved_fields: tuple[BlockingUnresolvedField, ...]
    implementation_overrides: tuple[ImplementationOverride, ...]
    implementation_view: dict[str, dict[str, Any]]
    downstream_context: dict[str, Any] | None
    connector_ready: bool

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    def to_json(self, *, indent: int = 2) -> str:
        return json.dumps(self.to_dict(), indent=indent, allow_nan=False) + "\n"

    def write_json(self, path: str | Path) -> None:
        Path(path).write_text(self.to_json(), encoding="utf-8")


def semantic_spec_sha256(spec: DatasetSpec) -> str:
    """Return the stable digest binding decisions to a semantic snapshot."""
    return hashlib.sha256(spec.to_json().encode()).hexdigest()


def detect_blocking_unresolved_fields(
    spec: DatasetSpec,
    requirements: tuple[DownstreamRequirement, ...],
) -> tuple[BlockingUnresolvedField, ...]:
    """Return downstream-required fields whose semantic status is unresolved."""
    blockers = []
    seen: set[str] = set()
    for requirement in requirements:
        _validate_requirement(requirement)
        if requirement.field_path in seen:
            raise ImplementationHandoffError(
                f"duplicate downstream requirement for {requirement.field_path!r}"
            )
        seen.add(requirement.field_path)
        target = _resolve_field(spec, requirement.field_path)
        claim = _resolution_claim(target, requirement.field_path)
        if claim.status is not EvidenceStatus.UNRESOLVED:
            continue
        blockers.append(
            BlockingUnresolvedField(
                field_path=requirement.field_path,
                semantic_resolution=claim.status.value,
                semantic_value=_json_value(target),
                downstream_system=requirement.downstream_system,
                requirement=requirement.requirement,
                best_supported_candidate=requirement.best_supported_candidate,
                supporting_evidence_refs=requirement.supporting_evidence_refs,
                remaining_uncertainty=requirement.remaining_uncertainty,
            )
        )
    return tuple(blockers)


def build_connector_handoff(
    spec: DatasetSpec,
    artifact: ImplementationOverrideArtifact,
    *,
    evidence_ids: set[str] | None = None,
) -> ConnectorHandoff:
    """Validate overrides and build a deterministic connector-facing view."""
    digest = semantic_spec_sha256(spec)
    if artifact.dataset_id != spec.identity.dataset_id:
        raise ImplementationHandoffError(
            f"override dataset_id {artifact.dataset_id!r} does not match "
            f"{spec.identity.dataset_id!r}"
        )
    if artifact.semantic_spec_sha256 != digest:
        raise ImplementationHandoffError(
            "override artifact targets a different semantic-spec snapshot"
        )

    blockers = detect_blocking_unresolved_fields(spec, artifact.requirements)
    if evidence_ids is not None and any(
        reference not in evidence_ids
        for requirement in artifact.requirements
        for reference in requirement.supporting_evidence_refs
    ):
        raise ImplementationHandoffError(
            "downstream requirement references evidence absent from the bounded evidence run"
        )
    requirements = {item.field_path: item for item in artifact.requirements}
    overrides: dict[str, ImplementationOverride] = {}
    override_ids: set[str] = set()
    for override in artifact.overrides:
        if override.field_path in overrides:
            raise ImplementationHandoffError(
                f"duplicate or conflicting overrides for {override.field_path!r}"
            )
        if override.override_id in override_ids:
            raise ImplementationHandoffError(
                f"duplicate implementation override id {override.override_id!r}"
            )
        requirement = requirements.get(override.field_path)
        if requirement is None:
            raise ImplementationHandoffError(
                f"override field {override.field_path!r} has no downstream requirement"
            )
        target = _resolve_field(spec, override.field_path)
        claim = _resolution_claim(target, override.field_path)
        if claim.status is not EvidenceStatus.UNRESOLVED:
            raise ImplementationHandoffError(
                f"field {override.field_path!r} is {claim.status.value}, not unresolved; "
                "an implementation override cannot replace semantic truth"
            )
        _validate_override(override, requirement, evidence_ids)
        overrides[override.field_path] = override
        override_ids.add(override.override_id)

    implementation_view = {
        path: {
            "value": override.value,
            "value_source": override.source,
            "override_id": override.override_id,
            "semantic_resolution": "unresolved",
        }
        for path, override in sorted(overrides.items())
    }
    unresolved_paths = {item.field_path for item in blockers}
    return ConnectorHandoff(
        schema_version="1.0",
        dataset_id=spec.identity.dataset_id,
        semantic_spec_sha256=digest,
        semantic_spec=spec.to_dict(),
        blocking_unresolved_fields=blockers,
        implementation_overrides=tuple(overrides[path] for path in sorted(overrides)),
        implementation_view=implementation_view,
        downstream_context=artifact.downstream_context,
        connector_ready=unresolved_paths <= set(overrides),
    )


def _validate_requirement(requirement: DownstreamRequirement) -> None:
    if not isinstance(requirement.field_path, str) or not requirement.field_path.strip():
        raise ImplementationHandoffError("downstream requirement needs a field_path")
    if (
        not isinstance(requirement.downstream_system, str)
        or not requirement.downstream_system.strip()
    ):
        raise ImplementationHandoffError("downstream requirement needs a downstream_system")
    if not isinstance(requirement.requirement, str) or not requirement.requirement.strip():
        raise ImplementationHandoffError("downstream requirement needs an explanation")
    if any(
        not isinstance(reference, str) or not reference.startswith("ev_")
        for reference in requirement.supporting_evidence_refs
    ):
        raise ImplementationHandoffError(
            "downstream requirement supporting_evidence_refs must be evidence IDs"
        )


def _validate_override(
    override: ImplementationOverride,
    requirement: DownstreamRequirement,
    evidence_ids: set[str] | None,
) -> None:
    if not isinstance(override.override_id, str) or not override.override_id.strip():
        raise ImplementationHandoffError("implementation override needs an override_id")
    if override.source != HUMAN_CONFIRMATION:
        raise ImplementationHandoffError(
            "implementation override source must be explicit human_confirmation"
        )
    if not isinstance(override.approved_by, str) or not override.approved_by.strip():
        raise ImplementationHandoffError("human confirmation must identify approved_by")
    if override.value is None:
        raise ImplementationHandoffError("implementation override value must not be null")
    if not isinstance(override.rationale, str) or not override.rationale.strip():
        raise ImplementationHandoffError("implementation override needs a rationale")
    if override.downstream_system != requirement.downstream_system:
        raise ImplementationHandoffError(
            "implementation override downstream_system does not match its requirement"
        )
    if any(
        not isinstance(reference, str) or not reference.startswith("ev_")
        for reference in override.evidence_refs
    ):
        raise ImplementationHandoffError(
            "implementation override evidence_refs must be evidence IDs"

"""Deterministic validation of semantic DatasetSpecs against DatasetProfiles."""

from __future__ import annotations

from dataclasses import asdict, dataclass, field
import json
from math import isclose
import re
from typing import Any

from ..models import DatasetProfile
from .models import (
    DatasetSpec,
    EvidenceClaim,
    EvidenceStatus,
    IndexBase,
    IndexConversion,
    SamplingRateClaim,
    TimeAxisKind,
    VariableRole,
)


@dataclass(frozen=True)
class ValidationIssue:
    code: str
    path: str
    message: str
    details: dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class ValidationResult:
    valid: bool
    errors: tuple[ValidationIssue, ...]

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    def to_json(self, *, indent: int = 2) -> str:
        return json.dumps(self.to_dict(), indent=indent, allow_nan=False) + "\n"


def validate_dataset_spec(profile: DatasetProfile, spec: DatasetSpec,
                          *, evidence_ids: set[str] | None = None) -> ValidationResult:
    """Return repair-oriented issues instead of raising for ordinary validation failures."""
    issues: list[ValidationIssue] = []

    def add(code: str, path: str, message: str, **details: Any) -> None:
        issues.append(ValidationIssue(code, path, message, details))

    accepted_ids = {spec.identity.dataset_id, *spec.identity.compatible_profile_ids}
    if profile.dataset_id not in accepted_ids:
        add(
            "DATASET_ID_MISMATCH", "identity.dataset_id",
            f"Profile dataset_id {profile.dataset_id!r} is not declared by the spec.",
            observed=profile.dataset_id, accepted=sorted(accepted_ids),
        )

    observed_boundary = profile.observed_structure.get("record_boundary")
    if observed_boundary != spec.record_discovery.boundary:
        add("RECORD_BOUNDARY_MISMATCH", "record_discovery.boundary",
            "Record-discovery boundary does not match the profiled structure.",
            claimed=spec.record_discovery.boundary, observed=observed_boundary)
    observed_subset = profile.source.get("scope")
    normalized_subsets = {_normalized_text(value) for value in spec.identity.source_subsets}
    if observed_subset and _normalized_text(str(observed_subset)) not in normalized_subsets:
        add("SOURCE_SUBSET_MISMATCH", "identity.source_subsets",
            f"Profile source scope {observed_subset!r} is not declared by the spec.",
            observed=observed_subset)

    observed_schema = profile.observed_structure.get("variable_schema", {})
    summaries = {item.get("observed_name"): item for item in profile.signals}
    declared = {item.name: item for item in spec.source_variables}
    for index, variable in enumerate(spec.source_variables):
        if variable.name not in observed_schema:
            add(
                "UNKNOWN_SOURCE_VARIABLE", f"source_variables[{index}].name",
                f"Variable {variable.name!r} does not exist in DatasetProfile.",
                source_variable=variable.name,
            )

    observed_runs = {run.source_run_id for run in profile.runs}
    for index, run_id in enumerate(spec.record_discovery.included_run_ids):
        if run_id not in observed_runs:
            add(
                "UNKNOWN_RUN_REFERENCE", f"record_discovery.included_run_ids[{index}]",
                f"Run {run_id!r} does not exist in DatasetProfile.", source_run_id=run_id,
            )

    run_rates = [run.sampling_rate_hz for run in profile.runs]
    axes = {axis.name: axis for axis in spec.time_axes}
    strict_evidence_refs = spec.schema_version == "0.2"
    for index, axis in enumerate(spec.time_axes):
        path = f"time_axes[{index}]"
        if axis.kind is TimeAxisKind.IMPLICIT_REGULAR:
            if axis.source_variable is not None:
                add("IMPLICIT_CLOCK_HAS_SOURCE", f"{path}.source_variable",
                    "An implicit regular clock must not name a raw source variable.")
            if axis.embedded_signal_row is not None:
                add("IMPLICIT_CLOCK_HAS_EMBEDDED_ROW", f"{path}.embedded_signal_row",
                    "An implicit regular clock cannot use an embedded timestamp row.")
            if (isinstance(axis.sample_index_origin, bool)
                    or not isinstance(axis.sample_index_origin, int)
                    or axis.sample_index_origin < 0):
                add("INVALID_SAMPLE_INDEX_ORIGIN", f"{path}.sample_index_origin",
                    "An implicit regular clock requires a non-negative integer index origin.")
            _validate_sampling_rate(axis.sampling_rate, run_rates=[run.sampling_rate_hz for run in profile.runs],
                                    path=f"{path}.sampling_rate", add=add,
                                    strict_evidence_refs=strict_evidence_refs,
                                    evidence_ids=evidence_ids)
            if axis.monotonic is not True:
                add("IMPLICIT_CLOCK_NOT_MONOTONIC", f"{path}.monotonic",
                    "A positive-rate implicit regular clock is structurally monotonic.")
        else:
            _check_reference(axis.source_variable, VariableRole.TIME,
                             f"{path}.source_variable", declared, add)
            if axis.source_variable not in observed_schema:
                add("TIME_AXIS_NOT_OBSERVED", f"{path}.source_variable",
                    f"Time variable {axis.source_variable!r} was not observed.")
            if axis.monotonic and any(run.timestamps_monotonic is not True for run in profile.runs):
                add("TIME_AXIS_NOT_MONOTONIC", f"{path}.monotonic",
                    "The spec requires a monotonic time axis, but not every run verifies it.")

    sequence_lengths = {run.sequence_length for run in profile.runs if run.sequence_length is not None}
    for index, signal in enumerate(spec.signals):
        path = f"signals[{index}]"
        _check_reference(signal.source_variable, VariableRole.SIGNAL, f"{path}.source_variable", declared, add)
        summary = summaries.get(signal.source_variable)
        if summary is None:
            continue
        observed_counts = summary.get("data_channel_count")
        if not observed_counts or set(observed_counts) != {signal.channels.count}:
            add("CHANNEL_COUNT_MISMATCH", f"{path}.channels.count",
                f"Claimed {signal.channels.count} channels do not match observed {observed_counts}.",
                claimed=signal.channels.count, observed=observed_counts)
        if (len(signal.channels.source_indices) != signal.channels.count
                or len(signal.channels.target_names) != signal.channels.count):
            add("CHANNEL_MAPPING_COUNT_MISMATCH", f"{path}.channels",
                "Channel count, source indices, and target names must have equal lengths.")
        shapes = summary.get("observed_shapes", [])
        channel_axis = summary.get("channel_axis", 0)
        row_counts = {shape[channel_axis] for shape in shapes
                      if shape and channel_axis is not None and channel_axis < len(shape)}
        source_indices = signal.channels.source_indices
        if (len(set(source_indices)) != len(source_indices)
                or any(index < 0 or any(index >= rows for rows in row_counts)
                       for index in source_indices)):
            add("INVALID_CHANNEL_MAPPING", f"{path}.channels.source_indices",
                "Source channel indices must be unique and within every observed matrix shape.",
                source_indices=source_indices, observed_row_counts=sorted(row_counts))
        observed_dtypes = summary.get("observed_dtypes", [])
        if spec.schema_version == "0.2":
            claimed_dtypes = list(signal.observed_dtypes)
            if signal.dtype is not None:
                add("INVALID_DTYPE_REPRESENTATION", f"{path}.dtype",
                    "DatasetSpec v0.2 represents physical storage types in observed_dtypes.")
            if len(set(claimed_dtypes)) != len(claimed_dtypes):
                add("DUPLICATE_OBSERVED_DTYPE", f"{path}.observed_dtypes",
                    "Observed dtype values must be unique.")
            if set(claimed_dtypes) != set(observed_dtypes):
                add("DTYPE_SET_MISMATCH", f"{path}.observed_dtypes",
                    "Claimed physical dtypes do not match the profiled dtype set.",
                    claimed=sorted(set(claimed_dtypes)), observed=sorted(set(observed_dtypes)))
        elif signal.dtype not in observed_dtypes:
            add("DTYPE_MISMATCH", f"{path}.dtype",
                f"Claimed dtype {signal.dtype!r} is not among observed dtypes {observed_dtypes!r}.")
        if signal.sampling.time_axis not in axes:
            add("UNKNOWN_TIME_AXIS", f"{path}.sampling.time_axis",
                f"Time axis {signal.sampling.time_axis!r} is not declared.")
        if spec.schema_version == "0.2" and signal.sampling.rate_hz is not None:
            add("LEGACY_SAMPLING_RATE", f"{path}.sampling.rate_hz",
                "DatasetSpec v0.2 stores sampling-rate provenance on the referenced time axis.")
        elif signal.sampling.rate_hz is not None:
            bad_rates = [rate for rate in run_rates if rate is None or not isclose(
                rate, signal.sampling.rate_hz, rel_tol=1e-9, abs_tol=1e-9)]
            if bad_rates:
                add("SAMPLING_RATE_MISMATCH", f"{path}.sampling.rate_hz",
                    f"Claimed {signal.sampling.rate_hz} Hz does not match every run.",
                    claimed=signal.sampling.rate_hz, observed=run_rates)
        sample_axis = summary.get("sample_axis", -1)
        signal_lengths = {shape[sample_axis] for shape in shapes
                          if shape and sample_axis is not None and abs(sample_axis) < len(shape)}
        if sequence_lengths and signal_lengths != sequence_lengths:
            add("SEQUENCE_LENGTH_MISMATCH", f"{path}.source_variable",
                "Signal sample dimensions do not match profiled run sequence lengths.",
                signal_lengths=sorted(signal_lengths), run_lengths=sorted(sequence_lengths))
        _check_claim(signal.unit.resolution, f"{path}.unit.resolution", add,
                     strict_evidence_refs=strict_evidence_refs, evidence_ids=evidence_ids)
        if signal.unit.resolution.status is EvidenceStatus.UNRESOLVED:
            if signal.unit.name is not None or signal.unit.symbol is not None:
                add("INVALID_UNIT_CLAIM", f"{path}.unit",
                    "Unresolved units must use null name and symbol fields.")
        elif not signal.unit.name or not signal.unit.symbol:
            add("INVALID_UNIT_CLAIM", f"{path}.unit",
                "Resolved unit information requires non-empty name and symbol fields.")
        if signal.unit.resolution.status is EvidenceStatus.OBSERVED:
            observed_unit = summary.get("observed_unit")
            if observed_unit is None:
                add("UNIT_NOT_OBSERVED", f"{path}.unit.resolution.status",
                    "The spec calls this unit observed, but DatasetProfile contains no observed unit.")
            else:
                observed_name = (observed_unit.get("name") if isinstance(observed_unit, dict)
                                 else str(observed_unit))
                if signal.unit.name != observed_name:
                    add("UNIT_MISMATCH", f"{path}.unit.name",
                        "Claimed unit does not match the unit observed in DatasetProfile.",
                        claimed=signal.unit.name, observed=observed_unit)
        _check_claim(signal.semantics, f"{path}.semantics", add,
                     strict_evidence_refs=strict_evidence_refs, evidence_ids=evidence_ids)

    for index, event_mapping in enumerate(spec.events):
        path = f"events[{index}]"
        _check_reference(event_mapping.source_variable, VariableRole.EVENT,
                         f"{path}.source_variable", declared, add)
        if event_mapping.source_variable not in observed_schema or not any(
                run.events for run in profile.runs):
            add("INVALID_EVENT_SOURCE", f"{path}.source_variable",
                f"Event source {event_mapping.source_variable!r} is not supported by the profile.")
        if event_mapping.time_axis not in axes:
            add("UNKNOWN_TIME_AXIS", f"{path}.time_axis",
                f"Time axis {event_mapping.time_axis!r} is not declared.")
        valid_pair = (
            (event_mapping.source_index_base is IndexBase.MATLAB_ONE_BASED
             and event_mapping.index_conversion is IndexConversion.SUBTRACT_ONE)
            or (event_mapping.source_index_base is IndexBase.ZERO_BASED
                and event_mapping.index_conversion is IndexConversion.IDENTITY)
        )
        if not valid_pair:
            add("INVALID_INDEX_BASE_CONVERSION", f"{path}.index_conversion",
                "Index conversion is incompatible with the declared source index base.")
        for run in profile.runs:
            for event in run.events:
                python_index = (event.observed_index - 1 if
                                event_mapping.index_conversion is IndexConversion.SUBTRACT_ONE
                                else event.observed_index)
                if run.sequence_length is None or not 0 <= python_index < run.sequence_length:
                    add("EVENT_INDEX_OUT_OF_BOUNDS", f"{path}.source_variable",
                        f"Event {event.event_id!r} converts to out-of-bounds index {python_index}.",
                        source_run_id=run.source_run_id, observed_index=event.observed_index,
                        converted_index=python_index, sequence_length=run.sequence_length)
                    continue
                if (event.inferred_time_seconds is not None and run.sampling_rate_hz is not None
                        and run.time_start is not None):
                    expected = run.time_start + python_index / run.sampling_rate_hz
                    if not isclose(event.inferred_time_seconds, expected, rel_tol=0.0, abs_tol=1e-9):
                        add("EVENT_TIMESTAMP_MISMATCH", f"{path}.timestamp_rule",
                            f"Event {event.event_id!r} timestamp disagrees with its converted index.",
                            source_run_id=run.source_run_id, converted_index=python_index,
                            expected=expected, observed=event.inferred_time_seconds)
        _check_claim(event_mapping.semantics, f"{path}.semantics", add,
                     strict_evidence_refs=strict_evidence_refs, evidence_ids=evidence_ids)

    available = {
        "source_run_id": all(bool(run.source_run_id) for run in profile.runs),
        "source_files": all(bool(run.source_files) for run in profile.runs),
        "source_subset": bool(profile.source.get("scope")),
        "series_source_id": all(bool(run.source_run_id) for run in profile.runs),
    }
    for index, requirement in enumerate(spec.provenance):
        if requirement.required and not available.get(requirement.field, False):
            add("PROVENANCE_SOURCE_UNAVAILABLE", f"provenance[{index}].field",
                f"Required provenance field {requirement.field!r} cannot be produced from the profile.")

    return ValidationResult(valid=not issues, errors=tuple(issues))


def _check_reference(name: str, role: VariableRole, path: str,
                     declared: dict[str, Any], add: Any) -> None:
    variable = declared.get(name)
    if variable is None:
        add("UNDECLARED_SOURCE_VARIABLE", path,
            f"Source variable {name!r} is used but not declared in source_variables.")
    elif variable.role is not role:
        add("SOURCE_VARIABLE_ROLE_MISMATCH", path,
            f"Source variable {name!r} is declared as {variable.role.value}, expected {role.value}.")


def _check_claim(claim: EvidenceClaim, path: str, add: Any,
                 *, strict_evidence_refs: bool = False,
                 evidence_ids: set[str] | None = None) -> None:
    if claim.status in {EvidenceStatus.DOCUMENTED, EvidenceStatus.INFERRED}:
        if claim.confidence is None or not claim.evidence:
            add("MISSING_EVIDENCE_REFERENCE", path,
                f"{claim.status.value.title()} claims require confidence and evidence references.")
        elif any(not reference.strip() for reference in claim.evidence):
            add("INVALID_EVIDENCE_CLAIM", path,
                "Evidence references must be non-empty strings.")
        elif strict_evidence_refs and claim.status is EvidenceStatus.DOCUMENTED and not any(
                reference.startswith("ev_documentation_") for reference in claim.evidence):
            add("INVALID_DOCUMENTATION_EVIDENCE", path,
                "Documented claims require at least one documentation evidence ID.")
        elif strict_evidence_refs and any(
                not reference.startswith("ev_") for reference in claim.evidence):
            add("INVALID_EVIDENCE_REFERENCE", path,
                "Claims require evidence IDs returned by the bounded evidence session.")
        elif evidence_ids is not None and any(
                reference not in evidence_ids for reference in claim.evidence):
            add("UNKNOWN_EVIDENCE_REFERENCE", path,
                "Claim references were not returned by this bounded evidence run.")
    if claim.status is EvidenceStatus.UNRESOLVED and claim.confidence is not None:
        add("INVALID_EVIDENCE_CLAIM", path,
            "Unresolved claims must not declare confidence.")


def _validate_sampling_rate(claim: SamplingRateClaim | None, *, run_rates: list[float | None],
                            path: str, add: Any, strict_evidence_refs: bool,
                            evidence_ids: set[str] | None) -> None:
    if claim is None:
        add("MISSING_SAMPLING_RATE", path,
            "An implicit regular clock requires a sampling-rate claim.")
        return
    _check_claim(claim.resolution, f"{path}.resolution", add,
                 strict_evidence_refs=strict_evidence_refs, evidence_ids=evidence_ids)
    if claim.resolution.status is EvidenceStatus.UNRESOLVED:
        if claim.value is not None:
            add("INVALID_SAMPLING_RATE_CLAIM", f"{path}.value",
                "An unresolved sampling rate must have a null value.")
        return
    if claim.value is None or claim.value <= 0:
        add("INVALID_SAMPLING_RATE", f"{path}.value",
            "A resolved sampling rate must be positive.")
        return
    if claim.unit.casefold() not in {"hz", "hertz"}:
        add("INVALID_SAMPLING_RATE_UNIT", f"{path}.unit",
            "Sampling rate must use Hz or hertz.")
    observed = [rate for rate in run_rates if rate is not None]
    contradictions = [rate for rate in observed
                      if not isclose(rate, claim.value, rel_tol=1e-9, abs_tol=1e-9)]
    if contradictions:
        add("SAMPLING_RATE_CONTRADICTION", f"{path}.value",
            "The claimed sampling rate contradicts deterministic observations.",
            claimed=claim.value, observed=sorted(set(observed)))
    if (claim.resolution.status is EvidenceStatus.OBSERVED
            and (not observed or len(observed) != len(run_rates))):
        add("SAMPLING_RATE_NOT_OBSERVED", f"{path}.resolution.status",
            "An observed sampling-rate claim requires a rate for every profiled run.")


def _normalized_text(value: str) -> str:
    return " ".join(re.findall(r"[a-z0-9]+", value.casefold()))
from __future__ import annotations

import csv
import hashlib
from datetime import UTC, datetime
from pathlib import Path, PurePosixPath

from .formats.arrays import NumericArrayAdapter
from .formats.tabular import FormatAdapterError, TabularAdapter
from .jobs import ResourceFormat, ResourceProfile


class InventoryError(RuntimeError):
    pass


class ResourceInventory:
    def __init__(
        self,
        *,
        max_file_bytes: int = 25_000_000_000,
        max_probe_bytes: int = 65_536,
        max_columns: int = 10_000,
        tabular: TabularAdapter | None = None,
        arrays: NumericArrayAdapter | None = None,
    ):
        self.max_file_bytes = max_file_bytes
        self.max_probe_bytes = max_probe_bytes
        self.max_columns = max_columns
        self.tabular = tabular or TabularAdapter(max_columns=max_columns)
        self.arrays = arrays or NumericArrayAdapter()

    def inspect(
        self,
        *,
        ingestion_id: str,
        asset_id: str,
        logical_path: str,
        path: Path,
    ) -> ResourceProfile:
        source = path.resolve(strict=True)
        if not source.is_file():
            raise InventoryError("Resource is not a regular file")
        size = source.stat().st_size
        if size > self.max_file_bytes:
            raise InventoryError("Resource exceeds the configured inventory size limit")
        content_sha256 = self._sha256(source)
        format_, details = self._probe(source, logical_path, size)
        if format_ is not ResourceFormat.UNSUPPORTED:
            try:
                details |= self._schema_details(source, format_)
            except FormatAdapterError as exc:
                format_ = ResourceFormat.UNSUPPORTED
                details = {"reason": "FORMAT_SCHEMA_INVALID", "message": str(exc)}
        material = f"{ingestion_id}|{asset_id}|{logical_path}|{content_sha256}"
        return ResourceProfile(
            resource_id=f"res_{hashlib.sha256(material.encode()).hexdigest()[:24]}",
            ingestion_id=ingestion_id,
            asset_id=asset_id,
            logical_path=logical_path,
            size_bytes=size,
            content_sha256=content_sha256,
            format=format_,
            details=details,
            inspected_at=datetime.now(UTC),
        )

    def _schema_details(self, path: Path, format_: ResourceFormat) -> dict:
        if format_ in {ResourceFormat.CSV, ResourceFormat.TSV, ResourceFormat.PARQUET}:
            profile = self.tabular.inspect(path, format_)
            return {
                "rowCount": profile.row_count,
                "rowGroups": profile.row_groups,
                "columns": [
                    {
                        "name": column.name,
                        "dtype": column.dtype,
                        "nullable": column.nullable,
                    }
                    for column in profile.columns
                ],
            }
        profile = self.arrays.inspect(path, format_)
        return {
            "arrays": [
                {
                    "name": array.name,
                    "shape": list(array.shape),
                    "dtype": array.dtype,
                    "sizeBytes": array.size_bytes,
                }
                for array in profile.arrays
            ]
        }

    def _probe(
        self,
        path: Path,
        logical_path: str,
        size: int,
    ) -> tuple[ResourceFormat, dict]:
        extension = self._extension(logical_path)
        with path.open("rb") as source:
            prefix = source.read(min(size, self.max_probe_bytes))
            suffix = b""
            if size >= 4:
                source.seek(-4, 2)
                suffix = source.read(4)
        magic_format = self._magic_format(prefix, suffix)
        if magic_format is not None:
            if extension not in self._extensions_for(magic_format):
                return ResourceFormat.UNSUPPORTED, {
                    "reason": "EXTENSION_MAGIC_MISMATCH",
                    "detectedFormat": magic_format.value,
                    "extension": extension,
                }
            return magic_format, {"probeBytes": len(prefix)}
        if extension in {".csv", ".tsv"}:
            return self._probe_delimited(prefix, extension)
        return ResourceFormat.UNSUPPORTED, {
            "reason": "UNSUPPORTED_FORMAT",
            "extension": extension,
        }

    def _probe_delimited(
        self,
        prefix: bytes,
        extension: str,
    ) -> tuple[ResourceFormat, dict]:
        try:
            text = prefix.decode("utf-8-sig")
        except UnicodeDecodeError:
            return ResourceFormat.UNSUPPORTED, {"reason": "DELIMITED_TEXT_NOT_UTF8"}
        lines = [line for line in text.splitlines() if line.strip()][:20]
        if len(lines) < 2:
            return ResourceFormat.UNSUPPORTED, {"reason": "DELIMITED_TEXT_TOO_SHORT"}
        expected = "," if extension == ".csv" else "\t"
        try:
            dialect = csv.Sniffer().sniff("\n".join(lines), delimiters=",\t;|")
            rows = list(csv.reader(lines, dialect))
        except csv.Error:
            return ResourceFormat.UNSUPPORTED, {"reason": "DELIMITED_DIALECT_INVALID"}
        widths = {len(row) for row in rows}
        if dialect.delimiter != expected:
            return ResourceFormat.UNSUPPORTED, {
                "reason": "EXTENSION_DIALECT_MISMATCH",
                "detectedDelimiter": dialect.delimiter,
            }
        if len(widths) != 1 or not widths or next(iter(widths)) > self.max_columns:
            return ResourceFormat.UNSUPPORTED, {"reason": "DELIMITED_ROW_WIDTH_INVALID"}
        width = next(iter(widths))
        if width < 2:
            return ResourceFormat.UNSUPPORTED, {"reason": "DELIMITED_SINGLE_COLUMN"}
        format_ = ResourceFormat.CSV if extension == ".csv" else ResourceFormat.TSV
        return format_, {
            "delimiter": dialect.delimiter,
            "sampledRows": len(rows),
            "columnCount": width,
            "header": rows[0][: min(width, 100)],
        }

    @staticmethod
    def _magic_format(prefix: bytes, suffix: bytes) -> ResourceFormat | None:
        if prefix.startswith(b"PAR1") and suffix == b"PAR1":
            return ResourceFormat.PARQUET
        if prefix.startswith(b"\x93NUMPY"):
            return ResourceFormat.NPY
        if prefix.startswith(b"PK\x03\x04"):
            return ResourceFormat.NPZ
        if prefix.startswith(b"MATLAB 5.0 MAT-file"):
            return ResourceFormat.MAT
        if any(prefix[offset : offset + 8] == b"\x89HDF\r\n\x1a\n" for offset in (0, 512, 1024, 2048)):
            return ResourceFormat.HDF5
        return None

    @staticmethod
    def _extensions_for(format_: ResourceFormat) -> set[str]:
        return {
            ResourceFormat.PARQUET: {".parquet"},
            ResourceFormat.NPY: {".npy"},
            ResourceFormat.NPZ: {".npz"},
            ResourceFormat.MAT: {".mat"},
            ResourceFormat.HDF5: {".h5", ".hdf5", ".mat"},
        }[format_]

    @staticmethod
    def _extension(logical_path: str) -> str:
        return PurePosixPath(logical_path.casefold()).suffix

    @staticmethod
    def _sha256(path: Path) -> str:
        digest = hashlib.sha256()
        with path.open("rb") as source:
            for chunk in iter(lambda: source.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()
from __future__ import annotations

import hashlib
import json
from enum import StrEnum
from typing import ClassVar, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

from .jobs import IngestionJobStore, ResourceFormat, ResourceProfile


def _to_camel(value: str) -> str:
    head, *tail = value.split("_")
    return head + "".join(part.title() for part in tail)


class _WireModel(BaseModel):
    model_config = ConfigDict(
        alias_generator=_to_camel,
        populate_by_name=True,
        extra="forbid",
        str_strip_whitespace=True,
    )


class MappingLayout(StrEnum):
    WIDE_TABLE = "WIDE_TABLE"
    LONG_TABLE = "LONG_TABLE"
    NAMED_ARRAYS = "NAMED_ARRAYS"


class MappingValidationError(ValueError):
    pass


class ChannelSpec(_WireModel):
    selector: str = Field(min_length=1, max_length=500)
    name: str = Field(min_length=1, max_length=200)
    unit: str | None = Field(default=None, max_length=100)


class MappingSpec(_WireModel):
    schema_version: Literal["1.0"] = "1.0"
    job_revision: int = Field(ge=1)
    resource_id: str = Field(pattern=r"^res_[a-f0-9]{24}$")
    resource_sha256: str = Field(pattern=r"^[a-f0-9]{64}$")
    layout: MappingLayout
    record_selector: str | None = Field(default=None, max_length=500)
    time_selector: str = Field(min_length=1, max_length=500)
    channel_selector: str | None = Field(default=None, max_length=500)
    value_selector: str | None = Field(default=None, max_length=500)
    signal_selector: str | None = Field(default=None, max_length=500)
    sample_axis: int | None = Field(default=None, ge=0, le=8)
    channel_axis: int | None = Field(default=None, ge=0, le=8)
    channels: list[ChannelSpec] = Field(min_length=1, max_length=10_000)
    annotations: list[str] = Field(default_factory=list, max_length=100)

    @model_validator(mode="after")
    def layout_fields_match(self) -> MappingSpec:
        if len({channel.selector for channel in self.channels}) != len(self.channels):
            raise ValueError("channel selectors must be unique")
        if len({channel.name for channel in self.channels}) != len(self.channels):
            raise ValueError("channel names must be unique")
        if self.layout is MappingLayout.LONG_TABLE:
            if not self.channel_selector or not self.value_selector or self.signal_selector:
                raise ValueError("long mappings require channel and value selectors")
        elif self.layout is MappingLayout.NAMED_ARRAYS:
            if (
                not self.signal_selector
                or self.sample_axis is None
                or self.channel_axis is None
                or self.sample_axis == self.channel_axis
            ):
                raise ValueError("array mappings require distinct sample and channel axes")
        elif self.channel_selector or self.value_selector or self.signal_selector:
            raise ValueError("wide mappings use channel selectors directly")
        return self

    def require_confirmation_fields(self) -> None:
        if any(not channel.unit for channel in self.channels):
            raise MappingValidationError("Every mapped channel requires an explicit unit")


class MappingProposal(_WireModel):
    resource_id: str
    candidates: list[MappingSpec]
    issues: list[str]
    requires_confirmation: bool = True


class ConfirmedMapping(_WireModel):
    mapping_sha256: str = Field(pattern=r"^[a-f0-9]{64}$")
    mapping: MappingSpec
    created: bool


class MappingService:
    TIME_NAMES: ClassVar[tuple[str, ...]] = ("time", "timestamp", "time_seconds", "seconds", "t")
    RECORD_NAMES: ClassVar[tuple[str, ...]] = (
        "record",
        "record_id",
        "run",
        "run_id",
        "sequence",
        "sequence_id",
    )
    CHANNEL_NAMES: ClassVar[tuple[str, ...]] = (
        "channel",
        "channel_id",
        "signal",
        "signal_id",
    )
    VALUE_NAMES: ClassVar[tuple[str, ...]] = ("value", "measurement", "reading")

    def __init__(self, jobs: IngestionJobStore):
        self.jobs = jobs

    def proposals(self, ingestion_id: str) -> list[MappingProposal]:
        job = self.jobs.get(ingestion_id)
        return [self._proposal(job.job_revision, profile) for profile in self.jobs.list_resources(ingestion_id)]

    def confirm(self, ingestion_id: str, mapping: MappingSpec) -> ConfirmedMapping:
        mapping.require_confirmation_fields()
        profile = next(
            (
                item
                for item in self.jobs.list_resources(ingestion_id)
                if item.resource_id == mapping.resource_id
                and item.content_sha256 == mapping.resource_sha256
            ),
            None,
        )
        if profile is not None:
            self._validate_against_profile(mapping, profile)
        payload = mapping.model_dump(mode="json", by_alias=True)
        canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        digest = hashlib.sha256(canonical.encode()).hexdigest()
        persisted, created = self.jobs.confirm_mapping(
            ingestion_id=ingestion_id,
            expected_job_revision=mapping.job_revision,
            resource_id=mapping.resource_id,
            resource_sha256=mapping.resource_sha256,
            mapping_sha256=digest,
            mapping_payload=payload,
        )
        return ConfirmedMapping(
            mapping_sha256=digest,
            mapping=MappingSpec.model_validate(persisted),
            created=created,
        )

    @staticmethod
    def _validate_against_profile(mapping: MappingSpec, profile: ResourceProfile) -> None:
        if mapping.layout in {MappingLayout.WIDE_TABLE, MappingLayout.LONG_TABLE}:
            columns = {column["name"] for column in profile.details.get("columns", [])}
            required = {mapping.time_selector, *(mapping.annotations)}
            if mapping.record_selector:
                required.add(mapping.record_selector)
            if mapping.layout is MappingLayout.WIDE_TABLE:
                required.update(channel.selector for channel in mapping.channels)
            else:
                required.update({mapping.channel_selector, mapping.value_selector})
                if any(channel.selector == "*" for channel in mapping.channels):
                    raise MappingValidationError(
                        "Long-table channel values must be selected explicitly"
                    )
            if None in required or not required.issubset(columns):
                raise MappingValidationError("Mapping selector is absent from the tabular schema")
            return
        arrays = {
            array["name"]: array for array in profile.details.get("arrays", [])
        }
        required_arrays = {mapping.time_selector, mapping.signal_selector, *mapping.annotations}
        if None in required_arrays or not required_arrays.issubset(arrays):
            raise MappingValidationError("Mapping selector is absent from the array schema")
        signal_shape = arrays[mapping.signal_selector]["shape"]
        if max(mapping.sample_axis, mapping.channel_axis) >= len(signal_shape):
            raise MappingValidationError("Mapped array axis is outside the signal shape")
        if signal_shape[mapping.channel_axis] != len(mapping.channels):
            raise MappingValidationError("Mapped channel count differs from the signal array")
        time_shape = arrays[mapping.time_selector]["shape"]
        if len(time_shape) != 1 or time_shape[0] != signal_shape[mapping.sample_axis]:
            raise MappingValidationError("Mapped time array does not match the sample axis")

    def get(self, ingestion_id: str) -> ConfirmedMapping | None:
        payload = self.jobs.get_mapping_payload(ingestion_id)
        if payload is None:
            return None
        canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        return ConfirmedMapping(
            mapping_sha256=hashlib.sha256(canonical.encode()).hexdigest(),
            mapping=MappingSpec.model_validate(payload),
            created=False,
        )

    def _proposal(self, job_revision: int, profile: ResourceProfile) -> MappingProposal:
        if profile.format is ResourceFormat.UNSUPPORTED:
            return MappingProposal(
                resource_id=profile.resource_id,
                candidates=[],
                issues=[profile.details.get("reason", "UNSUPPORTED_FORMAT")],
            )
        if profile.format in {ResourceFormat.CSV, ResourceFormat.TSV, ResourceFormat.PARQUET}:
            return self._table_proposal(job_revision, profile)
        return self._array_proposal(job_revision, profile)

    def _table_proposal(self, job_revision: int, profile: ResourceProfile) -> MappingProposal:
        columns = profile.details.get("columns", [])
        names = [column["name"] for column in columns]
        lower = {name.casefold(): name for name in names}
        time_matches = [lower[name] for name in self.TIME_NAMES if name in lower]
        record_matches = [lower[name] for name in self.RECORD_NAMES if name in lower]
        channel_matches = [lower[name] for name in self.CHANNEL_NAMES if name in lower]
        value_matches = [lower[name] for name in self.VALUE_NAMES if name in lower]
        issues: list[str] = []
        if len(time_matches) != 1:
            issues.append("TIME_SELECTOR_AMBIGUOUS")
            return MappingProposal(resource_id=profile.resource_id, candidates=[], issues=issues)
        if len(record_matches) > 1:
            issues.append("RECORD_SELECTOR_AMBIGUOUS")
            return MappingProposal(resource_id=profile.resource_id, candidates=[], issues=issues)
        if len(channel_matches) > 1 or len(value_matches) > 1:
            issues.append("LONG_LAYOUT_AMBIGUOUS")
            return MappingProposal(resource_id=profile.resource_id, candidates=[], issues=issues)
        time = time_matches[0]
        record = record_matches[0] if record_matches else None
        channel = channel_matches[0] if channel_matches else None
        value = value_matches[0] if value_matches else None
        if channel and value:
            candidates = [
                MappingSpec(
                    job_revision=job_revision,
                    resource_id=profile.resource_id,
                    resource_sha256=profile.content_sha256,
                    layout=MappingLayout.LONG_TABLE,
                    record_selector=record,
                    time_selector=time,
                    channel_selector=channel,
                    value_selector=value,
                    channels=[ChannelSpec(selector="*", name="selected_channel", unit=None)],
                )
            ]
        else:
            numeric = {
                column["name"]
                for column in columns
                if column.get("dtype") not in {"string", "unknown", "bool"}
            }
            selected = [name for name in names if name in numeric and name not in {time, record}]
            candidates = (
                [
                    MappingSpec(
                        job_revision=job_revision,
                        resource_id=profile.resource_id,
                        resource_sha256=profile.content_sha256,
                        layout=MappingLayout.WIDE_TABLE,
                        record_selector=record,
                        time_selector=time,
                        channels=[ChannelSpec(selector=name, name=name, unit=None) for name in selected],

